import test from'node:test';import assert from'node:assert/strict';import{inspectBuildOnlySnapshot,createTypeRepairInstallGrant}from'./build-only-evidence.mjs';import{REPOSITORY,REPOSITORY_ID,WORKFLOW_ID,WORKFLOW_PATH}from'./release-policy.mjs';import{BUILD_ARTIFACT}from'./build-artifact.mjs';import{installationFixture}from'./staging-install-test-fixture.mjs';import{installHash,installJson}from'./ci-install-grant.mjs';
function fixture(){const f=installationFixture(),candidate=f.evidence.controller,run={...f.run,repository:{id:REPOSITORY_ID,full_name:REPOSITORY},workflow_id:WORKFLOW_ID,path:WORKFLOW_PATH,head_branch:'alpha',event:'workflow_dispatch',updated_at:new Date(f.now-500).toISOString()};const active=['resolve','build','deployment-hold'],skipped=['typecheck','migrations','runner-diagnostics','controller-tests','plan','test','browser','verify'];const jobs=[...active,...skipped].map((name,i)=>({id:200+i,name,run_id:run.id,run_attempt:1,head_sha:candidate,head_branch:'alpha',status:'completed',conclusion:active.includes(name)?'success':'skipped',started_at:f.producer.started_at,completed_at:f.producer.completed_at,steps:name==='resolve'?[{name:'Refuse invalid build-only execution',conclusion:'success'}]:name==='build'?[{name:'Canonical System Testing production build and byte bundle',conclusion:'success'},{name:'Publish mandatory canonical build packet',conclusion:'success'}]:[]}));const artifact={id:456,name:BUILD_ARTIFACT,digest:'sha256:'+'f'.repeat(64),expired:false,size_in_bytes:100,created_at:f.producer.completed_at,expires_at:new Date(f.now+86400000).toISOString(),workflow_run:{id:run.id,repository_id:REPOSITORY_ID,head_repository_id:REPOSITORY_ID,head_sha:candidate,head_branch:'alpha'}};const snapshot={run,jobs,artifacts:[artifact]},expected={candidate,controller:candidate,runId:run.id};const body={kind:'COMBINED_REQUIRED_COVERAGE_WITH_ERASED_FIXTURE_REPAIR',policy:'type-only-test-fixture-repair/v1',result:'ACCEPTED_WITH_AUTHENTICATED_ORIGINAL_PASSES',candidate,releaseAuthorized:false,fullGatePassCreated:false,originalRunConclusion:'failure',originalCompilerConclusion:'failure',originalFinalVerifierConclusion:'failure',wholeCompiler:{conclusion:'success'},retainedUnits:[{id:'original-unit'}]};const acceptance={...body,acceptanceSha256:installHash(installJson(body))};const evidence={kind:'AUTHENTICATED_CANONICAL_BUILD_ONLY_NOT_FULL_GATE',sha:candidate,controller:candidate,controllerBranch:'alpha',runId:run.id,artifact:{id:artifact.id,digest:artifact.digest},deploymentBaseline:f.evidence.baseline,baseline:f.evidence.baseline,build:{...f.evidence.build,source:candidate}};return{snapshot,expected,now:f.now,acceptance,evidence,baselineBuildId:f.baselineBuildId,environmentSha256:f.environmentSha256};}
test('exact build-only inventory is successful bytes, never full coverage',()=>{const f=fixture(),r=inspectBuildOnlySnapshot({...f.snapshot,expected:f.expected,now:f.now});assert.equal(r.fullGatePassCreated,false);assert.equal(r.releaseAuthorized,false);});
for(const[name,change]of[['foreign branch',f=>f.snapshot.run.head_branch='feature'],['rerun',f=>f.snapshot.run.run_attempt=2],['skipped build',f=>f.snapshot.jobs.find(j=>j.name==='build').conclusion='skipped'],['unexpected runtime tests',f=>f.snapshot.jobs.find(j=>j.name==='test').conclusion='success'],['missing guard',f=>f.snapshot.jobs[0].steps=[]],['gate receipt',f=>f.snapshot.artifacts[0].name='gate-evidence'],['foreign artifact',f=>f.snapshot.artifacts[0].workflow_run.head_sha='a'.repeat(40)]])test('refuses '+name,()=>{const f=fixture();change(f);assert.throws(()=>inspectBuildOnlySnapshot({...f.snapshot,expected:f.expected,now:f.now}));});
test('combined acceptance creates an exact ordinary byte-install grant without fake full PASS',()=>{const f=fixture(),g=createTypeRepairInstallGrant(f);assert.equal(g.source,f.evidence.sha);assert.equal(g.runId,f.snapshot.run.id);assert.equal(g.result,undefined);assert.notEqual(g.witnessFingerprint,f.acceptance.acceptanceSha256);assert.equal(f.acceptance.originalRunConclusion,'failure');});
test('new grant refuses altered acceptance or mismatched fresh build bytes',()=>{for(const change of [f=>f.acceptance.fullGatePassCreated=true,f=>f.evidence.sha='a'.repeat(40),f=>f.evidence.artifact.digest='sha256:'+'0'.repeat(64)]){const f=fixture();change(f);assert.throws(()=>createTypeRepairInstallGrant(f));}});

test('forward staging baseline without exact source prefix refuses',()=>{const f=fixture();f.evidence.deploymentBaseline='e'.repeat(40);assert.throws(()=>createTypeRepairInstallGrant(f),/forward-baseline/);});

import {inspectBonusRepairBuildOnlySnapshot} from './build-only-evidence.mjs';
function bonusFixture(){const f=fixture(),controller='dc74b804fcecb4bab3207e82c9b9f099b9bf13be',runId=40508894540;f.expected={candidate:'d52563c666d39074217ed42191866add4a2793a0',controller,runId};Object.assign(f.snapshot.run,{id:runId,head_sha:controller});for(const j of f.snapshot.jobs)Object.assign(j,{run_id:runId,head_sha:controller});Object.assign(f.snapshot.artifacts[0].workflow_run,{id:runId,head_sha:controller});return f;}
test('Bonus repair build inventory authenticates exact bytes without granting coverage or install authority',()=>{const f=bonusFixture();const r=inspectBonusRepairBuildOnlySnapshot({...f.snapshot,expected:f.expected,now:f.now});assert.equal(r.releaseAuthorized,false);assert.equal(r.fullGatePassCreated,false);assert.throws(()=>inspectBuildOnlySnapshot({...f.snapshot,expected:f.expected,now:f.now}));assert.throws(()=>createTypeRepairInstallGrant(f));});
for(const [name,mutate] of [['other source',f=>f.expected.candidate='a'.repeat(40)],['other controller',f=>f.expected.controller='b'.repeat(40)],['other run',f=>f.expected.runId++],['foreign artifact',f=>f.snapshot.artifacts[0].workflow_run.head_sha='a'.repeat(40)],['test execution claimed',f=>f.snapshot.jobs.find(j=>j.name==='test').conclusion='success'],['build skipped',f=>f.snapshot.jobs.find(j=>j.name==='build').conclusion='skipped'],['rerun',f=>f.snapshot.run.run_attempt=2],['stale build',f=>f.now+=86400001]])test('Bonus inventory refuses '+name,()=>{const f=bonusFixture();mutate(f);assert.throws(()=>inspectBonusRepairBuildOnlySnapshot({...f.snapshot,expected:f.expected,now:f.now}));});
